  // 超时 fetch 包装
  async function fetchWithTimeout(url: string, params: Record<string, any>, timeoutMs: number) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const res = await api.get(url, { params, signal: controller.signal });
      return res.data;
    } finally {
      clearTimeout(timer);
    }
  }

  // 加载热搜词榜 + 趋势产品（默认模式，一次请求）
  // force=true 强制绕过缓存
  async function loadTrends(country: string, force = false) {
    setKeywordState('loading');
    setProductState('loading');
    setKeywordError('');
    setProductError('');
    try {
      const cacheKey = `market:trends:${country}:default`;
      const result = await fetchWithCache<any>(cacheKey, '/market/trends', {
        ttl: DEFAULT_TTL,
        force,
        data: { country, limit: 6 },
      });
      const data = result.data;
      const keywords: any[] = data?.keywords || data?.items || [];
      const products: any[] = data?.trends || data?.items || [];
      // 默认模式同时返回 keywords 与 trends
      if (Array.isArray(data?.keywords) && Array.isArray(data?.trends)) {
        setKeywordList(data.keywords.slice(0, 6));
        setProductList(data.trends.slice(0, 6));
      } else if (Array.isArray(data?.items) && data.items.length > 0) {
        // 单 category 场景兜底
        const kw = data.items.filter((it: any) => it.name && (it.heatLevel || it.growth));
        setKeywordList(kw.slice(0, 6));
        setProductList(data.items.slice(0, 6));
      } else {
        setKeywordList([]);
        setProductList([]);
      }
      setKeywordState(keywords.length > 0 || data?.keywords ? 'idle' : 'error');
      setProductState(products.length > 0 || data?.trends ? 'idle' : 'error');
      if ((!data?.keywords || data.keywords.length === 0) && (!data?.items || data.items.length === 0)) {
        setKeywordState('error');
        setKeywordError('暂无热搜词数据');
      }
      if ((!data?.trends || data.trends.length === 0) && (!data?.items || data.items.length === 0)) {
        setProductState('error');
        setProductError('暂无趋势产品数据');
      }
    } catch (err: any) {
      const msg = err?.name === 'CanceledError' || err?.message?.includes('abort')
        ? '请求超时，请检查网络后重试'
        : (err?.response?.data?.error || err?.message || '加载失败');
      setKeywordState('error');
      setKeywordError(msg);
      setProductState('error');
      setProductError(msg);
      toast.error(msg);
    }
  }

