  // 搜索热搜词（搜索类 TTL 3 分钟，不强制刷新）
  function handleSearch(e: React.FormEvent) {
    e.preventDefault();
    const q = searchInput.trim();
    if (!q) return;
    setSearchQuery(q);
    setSearchState('loading');
    setSearchError('');
    setSearchResult(null);
    const cacheKey = `market:search:${activeCountry}:${q}`;
    fetchWithCache<any>(cacheKey, '/market/trends', {
      ttl: SEARCH_TTL,
      force: false,
      data: { country: activeCountry, limit: 6, q },
    })
      .then((result) => {
        const data = result.data;
        setSearchResult(data || {});
        const items: any[] = data?.items || data?.keywords || [];
        const verdict: string = data?.search?.verdict || data?.verdict || '';
        if (verdict === '未收录' || (items.length === 0 && !data?.keywords)) {
          setSearchState('error');
          setSearchError('未收录，建议自行查阅亚马逊ABA后台或Google Trends');
        } else {
          setSearchState('idle');
        }
      })
      .catch((err: any) => {
        const msg = err?.name === 'CanceledError' || err?.message?.includes('abort')
          ? '搜索超时，请稍后重试'
          : (err?.response?.data?.error || err?.message || '搜索失败');
        setSearchState('error');
        setSearchError(msg);
      });
  }

