import { useEffect, useState } from 'react';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Users, TrendingUp, RefreshCw, Sparkles, Copy, Check, Lightbulb } from 'lucide-react';
import { toast } from 'sonner';
import type { ThemeConfig } from '@/lib/theme';
import { fetchWithCache, DEFAULT_TTL } from '@/lib/cache';
import { logger } from '@lark-apaas/client-toolkit-lite';
import { UniversalLink, resolveAppUrl, copyToClipboard } from '@lark-apaas/client-toolkit-lite';
import type { ICrowdfundingProduct } from '@/data/crowdfunding';
import { CROWDFUNDING_CURATED_POOL, CROWDFUNDING_LAST_UPDATED } from '@/data/crowdfunding';
import { formatDistanceToNow, parseISO } from 'date-fns';
import { zhCN } from 'date-fns/locale';

interface CrowdfundingSectionProps {
  theme: ThemeConfig;
}

type DataSource = 'live' | 'static' | 'builtin';

const SOURCE_META: Record<DataSource, { label: string; bg: string; color: string }> = {
  live:    { label: '实时数据',     bg: 'bg-emerald-100', color: 'text-emerald-700' },
  static:  { label: '静态精选池',   bg: 'bg-amber-100',   color: 'text-amber-700' },
  builtin: { label: '内置精选池',   bg: 'bg-slate-100',   color: 'text-slate-600' },
};

// 完整提示词原文（用于一键复制，保留原文一字不改）
const CROWDFUNDING_PROMPT_TEXT = `你是一位资深的市场研究专家、全球电商选品师（Product Hunter）和潮流趋势分析师。请帮我检索、筛选并分析目前（2026年最新）国内外各大众筹平台及新品孵化平台上，最具潜力的众筹产品。

这次选品请跳出传统"工业流水线大件"的思维框架，重点帮我挖掘并定位以下四类具有独特流量和商业价值的【潜力爆款】项目：

1. 视觉美学类：具有强烈装饰画风格、海报风格、创意插画IP、小众视觉艺术的家居/文创周边。
2. 3D打印与数字化：3D打印创意成品、独特的3D打印配件、或者纯数字化的3D打印模型文件（STL/3MF等众筹项目）。
3. DIY与创客组装：需要用户亲自动手组装（DIY Kit）、解压拼装、手作手办、或可编程/定制的创意手工项目。
4. 小众与低客单：面向长尾垂直市场，且客单价相对较低、购买决策门槛低、适合冲动型消费或粉丝经济的轻量级产品。

请将搜索和分析的范围分为以下两大板块：
- 海外主流平台：重点关注 Kickstarter、Indiegogo 的 Art/Design（艺术与设计）、Technology（3D打印/开源硬件）、Games（含DIY桌游/微缩模型）品类，以及日本 Makuake、Campfire 的手工美学板块。
- 国内主流平台：重点关注 摩点网（国内垂类文创/DIY/潮玩众筹）、淘宝众筹、小米有品（文化创意/家居饰品类），以及小红书/抖音上近期爆火的独立设计师海报、3D打印创意改件、DIY手作材料包。

请用结构化的表格输出结果，表格需包含以下字段：
- 产品/项目名称与所属平台
- 核心分类（例如：复古海报风、3D打印模型/成品、DIY拼装套件、小众文创等）
- 核心卖点（Key Selling Point）：它如何通过颜值、动手乐趣、定制化或情感共鸣吸引核心圈层？
- 客单价区间（预估或实际众筹/零售价）
- 供应链与商业化建议（供应链复刻门槛是否低？是否适合做一件代发/POD定制/3D打印农场量产？在跨境电商或国内市场的变现潜力如何？）

最后，根据上述筛选结果，总结出当前最受年轻人追捧的 10个【视觉、动手与小众圈层】的未来选品趋势。`;

function formatUpdatedLabel(iso: string): string {
  try {
    return formatDistanceToNow(parseISO(iso), { addSuffix: true, locale: zhCN });
  } catch {
    return '每月更新';
  }
}

const platformStyles: Record<ICrowdfundingProduct['platform'], { bg: string; text: string; accent: string }> = {
  Kickstarter: { bg: 'bg-emerald-50', text: 'text-emerald-700', accent: 'bg-emerald-500' },
  Indiegogo: { bg: 'bg-purple-50', text: 'text-purple-700', accent: 'bg-purple-500' },
};

function validateList(data: any): data is { list: ICrowdfundingProduct[]; updatedAt?: string; source?: string } {
  return data && Array.isArray(data.list) && data.list.length > 0 && data.list.every(
    (item: any) => item && typeof item.name === 'string' && (item.platform === 'Kickstarter' || item.platform === 'Indiegogo')
  );
}

/**
 * 取内置精选池前 6 条作为最终兜底
 */
function getBuiltinFallback(): { list: ICrowdfundingProduct[]; updatedAt: string; source: DataSource } {
  const ks = CROWDFUNDING_CURATED_POOL.filter(p => p.platform === 'Kickstarter').sort((a, b) => b.backers - a.backers).slice(0, 3);
  const igg = CROWDFUNDING_CURATED_POOL.filter(p => p.platform === 'Indiegogo').sort((a, b) => b.backers - a.backers).slice(0, 3);
  return {
    list: [...ks, ...igg].sort((a, b) => b.backers - a.backers).slice(0, 6),
    updatedAt: new Date(CROWDFUNDING_LAST_UPDATED).toISOString(),
    source: 'builtin',
  };
}

export default function CrowdfundingSection({ theme }: CrowdfundingSectionProps) {
  const [list, setList] = useState<ICrowdfundingProduct[]>([]);
  const [loading, setLoading] = useState(true);
  const [source, setSource] = useState<DataSource>('builtin');
  const [updatedAt, setUpdatedAt] = useState('');
  const [promptOpen, setPromptOpen] = useState(false);
  const [copied, setCopied] = useState(false);

  const handleCopy = async (e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      await copyToClipboard(CROWDFUNDING_PROMPT_TEXT);
      setCopied(true);
      toast.success('已复制到剪贴板');
      setTimeout(() => setCopied(false), 2000);
    } catch {
      toast.error('复制失败，请手动选择复制');
    }
  };

  /**
   * 三层兜底加载：
   * L1: 后端接口实时抓取 → live
   * L2: 静态 JSON 文件 → static
   * L3: 前端内置精选池 → builtin（最终兜底，一定出数据）
   */
  const loadData = async (force = false) => {
    setLoading(true);

    // ===== L1: 后端接口 =====
    try {
      const result = await fetchWithCache<any>(
        'crowdfunding:hot:api',
        '/crowdfunding/hot?limit=6',
        { ttl: DEFAULT_TTL, force }
      );
      const data = result.data;
      if (validateList(data)) {
        const finalSource = (data.source === 'live' ? 'live' : 'static') as DataSource;
        setList(data.list.slice(0, 6));
        setSource(finalSource);
        setUpdatedAt(data.updatedAt || '');
        setLoading(false);
        return;
      }
      logger.warn('[crowdfunding] L1 返回数据格式异常，降级 L2');
    } catch (err: any) {
      logger.warn('[crowdfunding] L1 请求失败，降级 L2', String(err?.message || err));
    }

    // ===== L2: 静态 JSON 文件 =====
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 5000);
      const resp = await fetch(resolveAppUrl('/assets/crowdfunding.json'), {
        signal: controller.signal,
        headers: { Accept: 'application/json' },
      });
      clearTimeout(timeoutId);
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      const text = await resp.text();
      const data = JSON.parse(text);
      if (validateList(data)) {
        setList(data.list.slice(0, 6));
        setSource('static');
        setUpdatedAt(data.updatedAt || '');
        setLoading(false);
        return;
      }
      logger.warn('[crowdfunding] L2 静态文件格式异常，降级 L3');
    } catch (err: any) {
      logger.warn('[crowdfunding] L2 静态文件加载失败，降级 L3', String(err?.message || err));
    }

    // ===== L3: 前端内置精选池（最终兜底，一定出数据）=====
    const fb = getBuiltinFallback();
    setList(fb.list);
    setSource(fb.source);
    setUpdatedAt(fb.updatedAt);
    setLoading(false);
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleRefresh = () => {
    loadData(true);
    toast.success('已刷新');
  };

  const sourceMeta = SOURCE_META[source];

  return (
    <div className="space-y-3">
      {/* 顶部说明栏 */}
      <div className="flex items-center justify-between px-1">
        <div className="flex items-center gap-2">
          <Sparkles className="size-4" style={{ color: theme.primary }} />
          <span className="text-xs text-muted-foreground">
            全球众筹热门追踪 · 找灵感、看趋势、选方向
          </span>
        </div>
        <div className="flex items-center gap-2">
          <Badge className={`text-[11px] border-0 ${sourceMeta.bg} ${sourceMeta.color}`}>
            {sourceMeta.label}
          </Badge>
          {updatedAt && (
            <span className="text-[11px] text-muted-foreground">
              {formatUpdatedLabel(updatedAt)}
            </span>
          )}
          <button
            onClick={handleRefresh}
            className="p-1.5 rounded-md hover:bg-muted transition-colors text-muted-foreground hover:text-foreground"
            aria-label="刷新"
            disabled={loading}
          >
            <RefreshCw className={`size-3.5 ${loading ? 'animate-spin' : ''}`} />
          </button>
        </div>
      </div>

      {/* 提示词折叠卡片 */}
      <div
        className="rounded-lg border border-border/50 bg-card/30 overflow-hidden cursor-pointer hover:bg-card/50 transition-colors"
        onClick={() => setPromptOpen(v => !v)}
      >
        <div className="flex items-center justify-between px-3 py-2.5">
          <div className="flex items-center gap-2">
            <Lightbulb className="size-4" style={{ color: theme.primary }} />
            <span className="text-xs font-semibold">潜力线索提示词 · 全球众筹选品</span>
            <Badge variant="outline" className="text-[10px] font-normal h-5">
              一键复制
            </Badge>
          </div>
          <div className="flex items-center gap-1">
            <Button
              size="sm"
              variant="secondary"
              onClick={handleCopy}
              className="h-6 text-[11px] gap-1 px-2"
            >
              {copied ? (
                <>
                  <Check className="size-3" />
                  已复制
                </>
              ) : (
                <>
                  <Copy className="size-3" />
                  复制
                </>
              )}
            </Button>
            <span
              className="text-muted-foreground transition-transform duration-200 text-xs"
              style={{ transform: promptOpen ? 'rotate(180deg)' : 'rotate(0deg)' }}
            >
              ▼
            </span>
          </div>
        </div>
        {promptOpen && (
          <div className="border-t border-border/40 px-3 py-3 max-h-[500px] overflow-y-auto text-xs space-y-3">
            <div>
              <p className="font-semibold text-sm mb-1" style={{ color: theme.primary }}>
                你是一位资深的市场研究专家、全球电商选品师（Product Hunter）和潮流趋势分析师
              </p>
              <p className="text-muted-foreground">
                请帮我检索、筛选并分析目前（2026年最新）国内外各大众筹平台及新品孵化平台上，最具潜力的众筹产品。
              </p>
            </div>

            <div>
              <p className="font-semibold text-xs mb-1">四类【潜力爆款】项目重点挖掘：</p>
              <ol className="space-y-0.5 text-muted-foreground pl-4 list-decimal">
                <li><span className="text-foreground/80 font-medium">视觉美学类</span>：强烈装饰画风格、海报风格、创意插画IP、小众视觉艺术的家居/文创周边</li>
                <li><span className="text-foreground/80 font-medium">3D打印与数字化</span>：3D打印创意成品、独特配件、纯数字化模型文件（STL/3MF等）</li>
                <li><span className="text-foreground/80 font-medium">DIY与创客组装</span>：动手组装（DIY Kit）、解压拼装、手作手办、可编程/定制创意手工</li>
                <li><span className="text-foreground/80 font-medium">小众与低客单</span>：长尾垂直市场、低客单价、冲动消费/粉丝经济轻量级产品</li>
              </ol>
            </div>

            <div>
              <p className="font-semibold text-xs mb-1">搜索范围：</p>
              <ul className="space-y-0.5 text-muted-foreground pl-4 list-disc">
                <li><span className="text-foreground/80 font-medium">海外主流平台</span>：Kickstarter、Indiegogo（Art/Design、Technology 3D打印、Games桌游）；日本 Makuake、Campfire 手工美学</li>
                <li><span className="text-foreground/80 font-medium">国内主流平台</span>：摩点网（文创/DIY/潮玩）、淘宝众筹、小米有品；小红书/抖音独立设计师海报、3D打印改件、DIY手作材料包</li>
              </ul>
            </div>

            <div>
              <p className="font-semibold text-xs mb-1">输出表格字段：</p>
              <ul className="space-y-0.5 text-muted-foreground pl-4 list-disc">
                <li>产品/项目名称与所属平台</li>
                <li>核心分类（复古海报风 / 3D打印模型 / DIY拼装套件 / 小众文创 等）</li>
                <li>核心卖点（Key Selling Point）：颜值 / 动手乐趣 / 定制化 / 情感共鸣</li>
                <li>客单价区间（预估或实际众筹/零售价）</li>
                <li>供应链与商业化建议（复刻门槛 / POD定制 / 3D打印农场 / 跨境变现潜力）</li>
              </ul>
            </div>

            <div>
              <p className="font-semibold text-xs mb-1">趋势总结：</p>
              <p className="text-muted-foreground">
                最后总结当前最受年轻人追捧的 <span className="text-foreground/80 font-medium">10 个【视觉、动手与小众圈层】的未来选品趋势</span>。
              </p>
            </div>
          </div>
        )}
      </div>

      {/* Loading 骨架 */}
      {loading && list.length === 0 && (
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
          {Array.from({ length: 6 }).map((_, i) => (
            <div
              key={i}
              className="rounded-xl p-3 animate-pulse"
              style={{
                backgroundColor: theme.ui.glassBg,
                border: `1px solid ${theme.ui.glassBorder || theme.ui.cardBorder}`,
              }}
            >
              <div className="flex items-center gap-2 mb-2">
                <div className="size-8 rounded-md" style={{ backgroundColor: theme.primary + '15' }} />
                <div className="flex-1 h-3 rounded" style={{ backgroundColor: 'rgba(0,0,0,0.08)' }} />
              </div>
              <div className="h-2.5 w-full rounded mb-1" style={{ backgroundColor: 'rgba(0,0,0,0.06)' }} />
              <div className="h-2.5 w-4/5 rounded mb-2" style={{ backgroundColor: 'rgba(0,0,0,0.04)' }} />
              <div className="flex gap-1">
                <div className="h-4 w-12 rounded-full" style={{ backgroundColor: 'rgba(0,0,0,0.05)' }} />
                <div className="h-4 w-10 rounded-full" style={{ backgroundColor: 'rgba(0,0,0,0.05)' }} />
              </div>
            </div>
          ))}
        </div>
      )}

      {/* 正常展示（list 始终有数据，L3 兜底） */}
      {list.length > 0 && (
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
          {list.map((item) => {
            const style = platformStyles[item.platform];
            return (
              <Card
                key={item.id}
                className="border shadow-sm hover:shadow-md transition-all overflow-hidden"
                style={{
                  borderColor: theme.ui.cardBorder,
                  backgroundColor: theme.ui.glassBg,
                  backdropFilter: 'blur(10px) saturate(180%)',
                  WebkitBackdropFilter: 'blur(10px) saturate(180%)',
                  boxShadow: theme.ui.glassShadow,
                }}
              >
                <CardContent className="p-3.5">
                  {/* 头部：平台 + 进度 */}
                  <div className="flex items-center justify-between mb-2">
                    <Badge className={`text-[11px] ${style.bg} ${style.text} border-0`}>
                      {item.platform}
                    </Badge>
                    <div className="flex items-center gap-1 text-[11px] font-semibold" style={{ color: theme.primary }}>
                      <TrendingUp className="size-3" />
                      {item.progress}
                    </div>
                  </div>

                  {/* 产品名 */}
                  <h4 className="font-semibold text-sm leading-snug mb-1.5 text-foreground">
                    {item.name}
                  </h4>

                  {/* 分类 */}
                  <div className="text-[11px] text-muted-foreground mb-2">
                    {item.category}
                  </div>

                  {/* 创新点 */}
                  <p className="text-xs text-secondary-strong leading-relaxed mb-3 line-clamp-3">
                    {item.innovation}
                  </p>

                  {/* 底部：支持人数 + 链接 */}
                  <div className="flex items-center justify-between pt-2 border-t" style={{ borderColor: theme.ui.cardBorder + '60' }}>
                    <div className="flex items-center gap-1.5 text-[11px] text-muted-foreground">
                      <Users className="size-3" />
                      <span>{item.backers.toLocaleString()} 人支持</span>
                    </div>
                    <UniversalLink
                      to={item.url}
                      className="flex items-center gap-1 text-[11px] font-medium hover:opacity-80 transition-opacity"
                      style={{ color: theme.primary }}
                    >
                      查看
                    </UniversalLink>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* 底部提示 */}
      <div className="px-1 text-[11px] text-muted-foreground flex items-start gap-1.5">
        <span>💡</span>
        <span>
          潜力线索用于选品灵感参考和趋势判断，不构成销售建议；
          选品前请自行评估专利风险、合规风险和供应链可行性。
        </span>
      </div>
    </div>
  );
}
